  .ss-feature { display: grid; grid-template-columns: minmax(0,1.05fr) minmax(280px,.95fr); gap: clamp(30px,5vw,68px); align-items: center; padding-bottom: 38px; border-bottom: 1px solid var(--border-default); }
  .ss-kicker { display: inline-flex; align-items: center; gap: 7px; color: var(--color-primary-500); font-size: 11px; font-weight: 800; letter-spacing: .11em; text-transform: uppercase; }
  .ss-kicker::before { content: ""; width: 18px; height: 2px; background: currentColor; }
