  .ss-art { min-height: 330px; border-radius: var(--radius-lg); overflow: hidden; border: 1px solid var(--border-default); background: var(--bg-subtle); position: relative; display: grid; place-items: center; }
  .ss-art::before { content: ""; position: absolute; inset: 0; background: radial-gradient(circle at 18% 20%, var(--color-primary-200), transparent 28%), linear-gradient(135deg, transparent 46%, var(--color-primary-100) 46% 54%, transparent 54%); opacity: .72; }
  .ss-art svg { position: relative; width: 72%; max-width: 300px; color: var(--text-primary); }
