  .ss-thumb { height: 122px; display: grid; place-items: center; overflow: hidden; background: var(--bg-subtle); border-bottom: 1px solid var(--border-default); }
  .ss-thumb svg { width: 64%; height: 64%; }
  .ss-card-body { padding: 17px 18px 16px; }
  .ss-card h4 { margin: 7px 0 7px; font: 700 20px/1.22 Georgia, 'Times New Roman', 'Noto Serif KR', serif; letter-spacing: -.018em; }
  .ss-card p { margin: 0; min-height: 44px; color: var(--text-secondary); font: 14px/1.55 Georgia, 'Times New Roman', 'Noto Serif KR', serif; }
  .ss-card-foot { margin-top: 15px; padding-top: 12px; border-top: 1px solid var(--border-subtle); display: flex; color: var(--text-tertiary); font-size: 11px; }
  .ss-card-foot span:last-child { margin-left: auto; }
  @media (max-width: 760px) {
    .ss-navlinks { display: none; }
    .ss-publication { padding-top: 32px; }
    .ss-feature { grid-template-columns: 1fr; }
    .ss-art { min-height: 240px; grid-row: 1; }
    .ss-grid { grid-template-columns: 1fr; }
